export interface StockItem {
  readonly sku: string;
  readonly quantity: number;
}

export interface Reservation {
  readonly id: string;
  readonly lines: readonly StockItem[];
  readonly status: "open" | "committed" | "cancelled";
}

interface MutableStock { available: number; reserved: number }
interface StoredReservation { id: string; lines: StockItem[]; status: Reservation["status"] }

export class ReservationBook {
  private readonly stock = new Map<string, MutableStock>();
  private readonly reservations = new Map<string, StoredReservation>();

  constructor(items: readonly StockItem[]) {
    for (const item of items) {
      if (item.sku.length === 0 || !Number.isInteger(item.quantity) || item.quantity < 0) {
        throw new TypeError("Invalid stock item");
      }
      if (this.stock.has(item.sku)) throw new TypeError("Duplicate SKU");
      this.stock.set(item.sku, { available: item.quantity, reserved: 0 });
    }
  }

  reserve(id: string, lines: readonly StockItem[]): Reservation {
    if (id.length === 0 || this.reservations.has(id)) throw new TypeError("Invalid reservation id");
    if (lines.length === 0) throw new TypeError("Reservation must contain lines");
    const seen = new Set<string>();
    for (const line of lines) {
      const item = this.stock.get(line.sku);
      if (seen.has(line.sku) || !Number.isInteger(line.quantity) || line.quantity <= 0) {
        throw new TypeError("Invalid reservation line");
      }
      if (item === undefined || item.available < line.quantity) {
        throw new Error("Stock unavailable");
      }
      seen.add(line.sku);
    }
    const copied = lines.map((line) => ({ ...line }));
    for (const line of copied) {
      const item = this.stock.get(line.sku)!;
      item.available -= line.quantity;
      item.reserved += line.quantity;
    }
    const stored: StoredReservation = { id, lines: copied, status: "open" };
    this.reservations.set(id, stored);
    return this.copyReservation(stored);
  }

  commit(id: string): Reservation {
    const reservation = this.requireOpen(id);
    for (const line of reservation.lines) {
      const item = this.stock.get(line.sku)!;
      item.reserved -= line.quantity;
      item.available += line.quantity;
    }
    reservation.status = "committed";
    return this.copyReservation(reservation);
  }

  cancel(id: string): Reservation {
    const reservation = this.requireOpen(id);
    for (const line of reservation.lines) {
      const item = this.stock.get(line.sku)!;
      item.reserved -= line.quantity;
      item.available += line.quantity;
    }
    reservation.status = "cancelled";
    return this.copyReservation(reservation);
  }

  snapshot(): {
    stock: Array<{ sku: string; available: number; reserved: number }>;
    reservations: Reservation[];
  } {
    return {
      stock: [...this.stock].map(([sku, value]) => ({ sku, ...value })).sort((a, b) => a.sku.localeCompare(b.sku)),
      reservations: [...this.reservations.values()].map((value) => this.copyReservation(value)).sort((a, b) => a.id.localeCompare(b.id)),
    };
  }

  private requireOpen(id: string): StoredReservation {
    const value = this.reservations.get(id);
    if (value === undefined || value.status !== "open") throw new Error("Reservation is not open");
    return value;
  }

  private copyReservation(value: StoredReservation): Reservation {
    return { id: value.id, status: value.status, lines: value.lines.map((line) => ({ ...line })) };
  }
}

