import { ReservationBook } from './solution';
import type { StockItem, Reservation } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function throwsKind(action: () => unknown, kind: 'TypeError' | 'Error', message: string): void {
  let error: unknown;
  try { action(); } catch (caught) { error = caught; }
  if (kind === 'TypeError') {
    if (!(error instanceof TypeError)) throw new Error(message);
  } else if (!(error instanceof Error)) {
    throw new Error(message);
  }
}

const constructorInput: StockItem[] = [
  { sku: 'z-last', quantity: 2 },
  { sku: 'a-first', quantity: 5 },
  { sku: 'empty-stock', quantity: 0 },
];
const book = new ReservationBook(constructorInput);
constructorInput[0] = { sku: 'z-last', quantity: 999 };

const initial = book.snapshot();
equal(initial.stock.length, 3, 'all stock rows included');
equal(initial.stock[0].sku, 'a-first', 'stock sorted by SKU');
equal(initial.stock[1].sku, 'empty-stock', 'stock lexical order');
equal(initial.stock[2].sku, 'z-last', 'stock lexical order end');
equal(initial.stock[2].available, 2, 'constructor input is copied');
equal(initial.stock[0].reserved, 0, 'initial reserved quantity');
equal(initial.reservations.length, 0, 'initial reservations empty');

const lines = [{ sku: 'z-last', quantity: 1 }, { sku: 'a-first', quantity: 2 }];
book.reserve('r-2', lines);
lines[0].quantity = 100;
lines.push({ sku: 'a-first', quantity: 1 });
book.reserve('r-1', [{ sku: 'a-first', quantity: 1 }]);

const open = book.snapshot();
equal(open.stock[0].available, 2, 'availability reduced by both reservations');
equal(open.stock[0].reserved, 3, 'reserved total accumulated');
equal(open.stock[2].available, 1, 'second SKU availability reduced');
equal(open.stock[2].reserved, 1, 'second SKU reserved total');
equal(open.reservations[0].id, 'r-1', 'reservations sorted lexically by id');
equal(open.reservations[1].id, 'r-2', 'second reservation order');
equal(open.reservations[1].status, 'open', 'new reservation is open');
equal(open.reservations[1].lines.length, 2, 'reserve line input was copied');
equal(open.reservations[1].lines[0].quantity, 1, 'copied reservation quantity unaffected by mutation');

const mutableSnapshot = open as unknown as {
  stock: Array<{ sku: string; available: number; reserved: number }>;
  reservations: Array<Reservation & { lines: Array<{ sku: string; quantity: number }> }>;
};
mutableSnapshot.stock[0].available = 999;
mutableSnapshot.reservations[1].lines[0].quantity = 999;
const afterSnapshotMutation = book.snapshot();
equal(afterSnapshotMutation.stock[0].available, 2, 'stock snapshot does not alias internals');
equal(afterSnapshotMutation.reservations[1].lines[0].quantity, 1, 'reservation snapshot does not alias internals');

book.commit('r-1');
const committed = book.snapshot();
equal(committed.reservations[0].status, 'committed', 'commit changes status');
equal(committed.stock[0].available, 2, 'commit does not restore availability');
equal(committed.stock[0].reserved, 2, 'commit removes quantity from reserved total');

book.cancel('r-2');
const cancelled = book.snapshot();
equal(cancelled.reservations[1].status, 'cancelled', 'cancel changes status');
equal(cancelled.stock[0].available, 4, 'cancel restores first SKU availability');
equal(cancelled.stock[0].reserved, 0, 'cancel removes first SKU reserved total');
equal(cancelled.stock[2].available, 2, 'cancel restores second SKU availability');
equal(cancelled.stock[2].reserved, 0, 'cancel removes second SKU reserved total');

throwsKind(() => book.commit('missing'), 'Error', 'unknown commit id must throw');
throwsKind(() => book.cancel('missing'), 'Error', 'unknown cancel id must throw');
throwsKind(() => book.commit('r-1'), 'Error', 'committed reservation cannot be committed again');
throwsKind(() => book.cancel('r-2'), 'Error', 'cancelled reservation cannot be cancelled again');

const atomic = new ReservationBook([{ sku: 'A', quantity: 3 }, { sku: 'B', quantity: 1 }]);
throwsKind(
  () => atomic.reserve('bad', [{ sku: 'A', quantity: 2 }, { sku: 'B', quantity: 2 }]),
  'Error',
  'insufficient stock must throw',
);
let atomicSnapshot = atomic.snapshot();
equal(atomicSnapshot.stock[0].available, 3, 'failed reservation is atomic for earlier line');
equal(atomicSnapshot.stock[1].available, 1, 'failed reservation leaves all stock unchanged');
equal(atomicSnapshot.reservations.length, 0, 'failed reservation is not recorded');
throwsKind(() => atomic.reserve('unknown', [{ sku: 'C', quantity: 1 }]), 'Error', 'unknown SKU throws');
atomic.reserve('used', [{ sku: 'A', quantity: 1 }]);
throwsKind(() => atomic.reserve('used', [{ sku: 'A', quantity: 1 }]), 'Error', 'duplicate reservation id throws');
atomicSnapshot = atomic.snapshot();
equal(atomicSnapshot.stock[0].available, 2, 'duplicate id failure leaves stock unchanged');

throwsKind(() => new ReservationBook([{ sku: '', quantity: 1 }]), 'TypeError', 'empty SKU rejected');
throwsKind(() => new ReservationBook([{ sku: 'A', quantity: -1 }]), 'TypeError', 'negative stock rejected');
throwsKind(() => new ReservationBook([{ sku: 'A', quantity: 1.5 }]), 'TypeError', 'fractional stock rejected');
throwsKind(() => new ReservationBook([{ sku: 'A', quantity: 1 }, { sku: 'A', quantity: 2 }]), 'TypeError', 'duplicate SKU rejected');
throwsKind(() => atomic.reserve('', [{ sku: 'A', quantity: 1 }]), 'TypeError', 'empty reservation id rejected');
throwsKind(() => atomic.reserve('dup-lines', [{ sku: 'A', quantity: 1 }, { sku: 'A', quantity: 1 }]), 'TypeError', 'duplicate line SKU rejected');
throwsKind(() => atomic.reserve('zero', [{ sku: 'A', quantity: 0 }]), 'TypeError', 'zero line quantity rejected');
throwsKind(() => atomic.reserve('fraction', [{ sku: 'A', quantity: 1.5 }]), 'TypeError', 'fractional line quantity rejected');

